"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { DashboardHeader } from "@/components/dashboard-header";
import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import {
  Plus,
  Eye,
  Pencil,
  Trash2,
  Search,
  MapPin,
  Loader2,
  Router,
  UserRound,
} from "lucide-react";
import { getAllSmartMeters, SmartMeter, deleteSmartMeter } from "@/lib/api/smartmeter";
import { useToast } from "@/hooks/use-toast";
import fetchWithAuth from "@/lib/fetchWithAuth";
import { useUser } from "@/context/UserContext";
import { useRouter } from "next/navigation";


export default function SmartMeterListPage() {
  const [page, setPage] = useState(1);
  const [limit] = useState(10);
  const [pagination, setPagination] = useState<{
    totalPages: number;
    totalCount: number;
    hasNextPage: boolean;
    hasPrevPage: boolean;
  } | null>(null);
  const [smartMeters, setSmartMeters] = useState<SmartMeter[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [deleting, setDeleting] = useState<string | null>(null);
  const { toast } = useToast();
  const router= useRouter();
  const {user}= useUser();


  
    useEffect(() => {
      if (!loading && user?.role !== "ADMIN") {
        router.replace("/forbidden");
      }
    }, [loading, user, router]);
    

  useEffect(() => {
    setPage(1);
  }, [searchTerm]);

  useEffect(() => {
    fetchSmartMeters();
  }, [page]);

  const fetchSmartMeters = async () => {
    setLoading(true);
    try {
      const response = await getAllSmartMeters({
        include: true,
        page,
        limit,
        search: searchTerm || undefined,
      });

      if (response.success && response.data && response.pagination) {
        setSmartMeters(response.data);
        setPagination(response.pagination);
      } else {
        toast({
          title: "Error",
          description: response.error || "Failed to fetch Smart Meters",
          variant: "destructive",
        });
      }
    } catch {
      toast({
        title: "Error",
        description: "Failed to fetch Smart Meters",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string, smartMeterId: string) => {
    setDeleting(id);
    try {
      const response = await deleteSmartMeter(id);

      if (response.success) {
        setSmartMeters((prev) => prev.filter((meter) => meter.id !== id));
        toast({
          title: "Success",
          description: `Smart Meter "${smartMeterId}" deleted successfully`,
        });
      } else {
        toast({
          title: "Error",
          description: response.error || "Failed to delete Smart Meter",
          variant: "destructive",
        });
      }
    } catch {
      toast({
        title: "Error",
        description: "Failed to delete Smart Meter",
        variant: "destructive",
      });
    } finally {
      setDeleting(null);
    }
  };

  const isActive = (status: string) => status?.toLowerCase() === "active";

  return (
    <div className="p-4 md:p-6 lg:p-8">
      <div className="mx-auto max-w-7xl">
        {/* Header */}
        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white md:text-3xl">
              Smart Meter Management
            </h1>
            <p className="mt-1 text-sm text-gray-400">
              Manage and monitor all surveillance areas
            </p>
          </div>

          {user?.role=="ADMIN"?(<Link href="/smartmeter/add">
            <Button className="gap-2 bg-[#8B0000] text-white hover:bg-[#6B0000]">
              <Plus className="h-4 w-4" />
              Add New Smart Meter
            </Button>
          </Link>):null}
          
        </div>

        {/* Search */}
        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center">
          <div className="relative flex-1 sm:max-w-xs">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-500" />
            <Input
              placeholder="Search SmartMeter..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  setPage(1);
                  fetchSmartMeters();
                }
              }}
              className="border-[#333] bg-[#222] pl-10 text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
            />
          </div>
          <p className="text-sm text-gray-400">
            Showing {smartMeters.length} of {pagination?.totalCount ?? 0} Smart Meters
          </p>
        </div>

        {/* Loading State */}
        {loading && (
          <div className="flex flex-col items-center justify-center rounded-lg border border-[#333] bg-[#222] py-12">
            <Loader2 className="mb-4 h-12 w-12 animate-spin text-[#8B0000]" />
            <p className="text-lg font-medium text-gray-400">Loading SmartMeters...</p>
          </div>
        )}

        {/* Table - Desktop */}
        {!loading && smartMeters.length > 0 && (
          <div className="hidden rounded-lg border border-[#333] bg-[#222] md:block">
            <Table>
              <TableHeader>
                <TableRow className="border-[#333] hover:bg-transparent">
                  <TableHead className="text-gray-400">Smart Meter ID</TableHead>
                  <TableHead className="text-gray-400">IP Address</TableHead>
                  <TableHead className="text-gray-400">Latitude</TableHead>
                  <TableHead className="text-gray-400">Longitude</TableHead>
                  <TableHead className="text-gray-400">Added By</TableHead>
                  <TableHead className="text-gray-400">Status</TableHead>
                  <TableHead className="text-right text-gray-400">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {smartMeters.map((meter) => (
                  <TableRow key={meter.id} className="border-[#333] hover:bg-[#2a2a2a]">
                    <TableCell className="font-medium text-white">
                      {meter.smartMeterId}
                    </TableCell>
                    <TableCell className="font-mono text-sm text-gray-300">
                      {meter.ipAddress || "N/A"}
                    </TableCell>
                    <TableCell className="font-mono text-sm text-gray-400">
                      {meter.latitude?.toFixed(4) ?? "N/A"}
                    </TableCell>
                    <TableCell className="font-mono text-sm text-gray-400">
                      {meter.longitude?.toFixed(4) ?? "N/A"}
                    </TableCell>
                    <TableCell>
                      <Badge className="bg-yellow-400/15 text-yellow-300 hover:bg-yellow-400/25">
                        {meter.addedBy || "N/A"}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge
                        className={
                          isActive(meter.status)
                            ? "bg-green-600/20 text-green-400 hover:bg-green-600/30"
                            : "bg-red-600/20 text-red-400 hover:bg-red-600/30"
                        }
                      >
                        {meter.status}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-1">
                        <Link href={`/smartmeter/${meter.id}`}>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-gray-400 hover:bg-[#333] hover:text-white"
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                        </Link>
                        <Link href={`/smartmeter/${meter.id}/edit`}>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-gray-400 hover:bg-[#333] hover:text-white"
                          >
                            <Pencil className="h-4 w-4" />
                          </Button>
                        </Link>
                        <AlertDialog>
                          <AlertDialogTrigger asChild>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8 text-gray-400 hover:bg-red-600/20 hover:text-red-400"
                              disabled={deleting === meter.id}
                            >
                              {deleting === meter.id ? (
                                <Loader2 className="h-4 w-4 animate-spin" />
                              ) : (
                                <Trash2 className="h-4 w-4" />
                              )}
                            </Button>
                          </AlertDialogTrigger>
                          <AlertDialogContent className="border-[#333] bg-[#222]">
                            <AlertDialogHeader>
                              <AlertDialogTitle className="text-white">
                                Delete SmartMeter
                              </AlertDialogTitle>
                              <AlertDialogDescription className="text-gray-400">
                                Are you sure you want to delete "{meter.smartMeterId}"?
                                This action cannot be undone and will also delete all
                                associated sensors and alarms.
                              </AlertDialogDescription>
                            </AlertDialogHeader>
                            <AlertDialogFooter>
                              <AlertDialogCancel className="border-[#333] bg-transparent text-white hover:bg-[#333]">
                                Cancel
                              </AlertDialogCancel>
                              <AlertDialogAction
                                onClick={() => handleDelete(meter.id, meter.smartMeterId)}
                                className="bg-red-600 text-white hover:bg-red-700"
                              >
                                Delete
                              </AlertDialogAction>
                            </AlertDialogFooter>
                          </AlertDialogContent>
                        </AlertDialog>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {/* Cards - Mobile */}
        {!loading && smartMeters.length > 0 && (
          <div className="flex flex-col gap-3 md:hidden">
            {smartMeters.map((meter) => (
              <div
                key={meter.id}
                className="rounded-xl border border-[#333] bg-[#222] p-4 transition-colors hover:border-[#8B0000]/40"
              >
                {/* Top row: ID + status */}
                <div className="mb-3 flex items-center justify-between">
                  <p className="text-sm font-semibold text-white">{meter.smartMeterId}</p>
                  <Badge
                    className={
                      isActive(meter.status)
                        ? "bg-green-600/20 text-green-400"
                        : "bg-red-600/20 text-red-400"
                    }
                  >
                    {meter.status}
                  </Badge>
                </div>

                {/* Meta grid */}
                <div className="mb-4 grid grid-cols-1 gap-2 rounded-lg border border-[#2a2a2a] bg-[#1a1a1a] p-3 text-sm">
                  <div className="flex items-center gap-2 text-gray-400">
                    <Router className="h-3.5 w-3.5 shrink-0 text-gray-500" />
                    <span className="font-mono text-gray-300">
                      {meter.ipAddress || "N/A"}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 text-gray-400">
                    <MapPin className="h-3.5 w-3.5 shrink-0 text-gray-500" />
                    <span className="font-mono text-gray-300">
                      {meter.latitude?.toFixed(4) ?? "N/A"},{" "}
                      {meter.longitude?.toFixed(4) ?? "N/A"}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 text-gray-400">
                    <UserRound className="h-3.5 w-3.5 shrink-0 text-gray-500" />
                    <span className="text-gray-300">{meter.addedBy || "N/A"}</span>
                  </div>
                </div>

                {/* Actions */}
                <div className="flex gap-2">
                  <Link href={`/smartmeter/${meter.id}`} className="flex-1">
                    <Button
                      variant="outline"
                      size="sm"
                      className="w-full gap-2 border-[#333] bg-transparent text-white hover:bg-[#333]"
                    >
                      <Eye className="h-4 w-4" />
                      View
                    </Button>
                  </Link>
                  <Link href={`/smartmeter/${meter.id}/edit`} className="flex-1">
                    <Button
                      variant="outline"
                      size="sm"
                      className="w-full gap-2 border-[#333] bg-transparent text-white hover:bg-[#333]"
                    >
                      <Pencil className="h-4 w-4" />
                      Edit
                    </Button>
                  </Link>
                  <AlertDialog>
                    <AlertDialogTrigger asChild>
                      <Button
                        variant="outline"
                        size="sm"
                        className="gap-2 border-[#333] bg-transparent text-red-400 hover:bg-red-600/20"
                        disabled={deleting === meter.id}
                      >
                        {deleting === meter.id ? (
                          <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                          <Trash2 className="h-4 w-4" />
                        )}
                      </Button>
                    </AlertDialogTrigger>
                    <AlertDialogContent className="border-[#333] bg-[#222]">
                      <AlertDialogHeader>
                        <AlertDialogTitle className="text-white">
                          Delete SmartMeter
                        </AlertDialogTitle>
                        <AlertDialogDescription className="text-gray-400">
                          Are you sure you want to delete "{meter.smartMeterId}"? This
                          action cannot be undone.
                        </AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel className="border-[#333] bg-transparent text-white hover:bg-[#333]">
                          Cancel
                        </AlertDialogCancel>
                        <AlertDialogAction
                          onClick={() => handleDelete(meter.id, meter.smartMeterId)}
                          className="bg-red-600 text-white hover:bg-red-700"
                        >
                          Delete
                        </AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Empty state */}
        {!loading && smartMeters.length === 0 && (
          <div className="flex flex-col items-center justify-center rounded-lg border border-[#333] bg-[#222] py-12">
            <MapPin className="mb-4 h-12 w-12 text-gray-600" />
            <p className="text-lg font-medium text-gray-400">No SmartMeter found</p>
            <Link href="/smartmeter/add">
              <p className="mt-1 text-sm text-[#8B0000] hover:underline">
                Add New SmartMeter
              </p>
            </Link>
          </div>
        )}

        {/* Pagination */}
        {!loading && pagination && pagination.totalPages > 1 && (
          <div className="mt-6 flex items-center justify-between">
            <Button
              variant="outline"
              disabled={!pagination.hasPrevPage}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              className="border-[#333] bg-transparent text-white hover:bg-[#333]"
            >
              Previous
            </Button>

            <p className="text-sm text-gray-400">
              Page {page} of {pagination.totalPages}
            </p>

            <Button
              variant="outline"
              disabled={!pagination.hasNextPage}
              onClick={() => setPage((p) => p + 1)}
              className="border-[#333] bg-transparent text-white hover:bg-[#333]"
            >
              Next
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}
